-- 1) New official source (no conicet.gov.ar URL existed in sources)
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3135, 'https://convocatorias.conicet.gov.ar/becas/convocatoria-vigente/', $$Convocatoria 2026 - Becas (Becas Internas Doctorales, Finalización de Doctorado, Postdoctorales, Cofinanciadas) | CONICET Convocatorias (official)$$, 'convocatorias.conicet.gov.ar', 'scholarship', now(), true, true, now()) RETURNING id, url;

-- 2) Retire 400 (invented composite name)
UPDATE scholarships SET title = $$Universidad de Buenos Aires - 'UBA Doctoral Fellowship CONICET Track' is an invented importer composite; the real instrument is CONICET's national Beca Interna Doctoral (retired)$$, provider = $$Universidad de Buenos Aires$$, country = $$Argentina$$, coverage_type = $$Unspecified$$, amount_usd_value = 0, award_amount = NULL, award_currency = NULL, award_period = NULL, award_basis = NULL, deadline = $$Retired - no award of this name exists, so there is no application round. The real national competition is CONICET's Beca Interna Doctoral (2026 call: applications ran 27 July-21 August 2026 via SIGEVA; about 1,000 fellowships; 60 months from 1 April 2027) - see the description before planning around any future call.$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[]$$, recurrence = $$none$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["PhD"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["RETIRED - invented importer composite; doctoral funding in Argentina runs through CONICET's national fellowship competitions, not a UBA-branded 'CONICET Track' (see description)"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$RETIRED in Pass 122 (2026-10-28) as an invented importer composite. There is no "UBA Doctoral Fellowship CONICET Track": the title welds the Universidad de Buenos Aires to CONICET (Argentina's national research council) as if the university ran a named doctoral fellowship under that label, and neither institution publishes any such award. The real landscape, from CONICET's official convocatorias portal fetched 2026-10-28: doctoral funding in Argentina runs through CONICET's national fellowship competitions ("Becas Internas"), which are university-agnostic - you compete nationally with a work plan, a director and a workplace (lugar de trabajo) that may be at UBA or any other Argentine institution. The 2026 call foresees 1,000 Becas Internas Doctorales of 60 months from 1 April 2027 (applications ran 27 July-21 August 2026 through the SIGEVA system; 70% allocated to officially prioritised topics/regions, 30% by merit order), alongside 300 Becas Internas de Finalización de Doctorado (24 months; for doctoral candidates without a CONICET doctoral fellowship), 800 Becas Internas Postdoctorales (call 18 February-5 March 2027; 36 months from 1 August 2027) and the company-cofunded doctoral/postdoctoral line (two windows a year). Who may compete, including the position of foreign applicants and any residence/dedication conditions, is governed by each call's Bases, which were not read in this pass - so no eligibility terms are asserted here; the CONICET competition is recorded as a candidate for a future additions batch under its own name after a bases-level verification. UBA's own position for foreign students was audited in record 693 (retired 2026-10-25): undergraduate study at UBA is free for Argentines and foreigners alike and only postgraduate study carries fees, the university's FAQ states there are no scholarships for its Study Abroad programme, and its beca listings are outbound mobility for its own students. An earlier importer incarnation of this row carried an invented USD 14,000 and an invented annual August-11 deadline (both removed 2026-10-26). Use CONICET's official convocatorias portal, not this record.$$ , requirements = $$Do not apply on the basis of this record - it is retired and names no real award. For doctoral funding in Argentina, the genuine channel is CONICET's Beca Interna Doctoral competition (national, via SIGEVA, with a director and an Argentine workplace; 60 months; annual calls - the 2026 round applied 27 July-21 August 2026): read the current call's Bases on the official CONICET Convocatorias portal for who may compete, including the rules for foreign applicants, before counting on it. UBA itself offers foreign degree students no institutional scholarship (audit record 693).$$ , website_url = $$https://convocatorias.conicet.gov.ar/becas/convocatoria-vigente/$$, source_url = $$https://convocatorias.conicet.gov.ar/becas/convocatoria-vigente/$$, application_url = $$https://convocatorias.conicet.gov.ar/becas/convocatoria-vigente/$$, funding_type = $$RETIRED - invented importer composite; the real instrument is CONICET's national Beca Interna Doctoral competition$$, tuition_coverage = $$RETIRED - no coverage of its own; see the description for the CONICET landscape and audit record 693 for UBA.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = $$Not applicable - retired record.$$ , required_documents = $$[]$$, application_status = $$closed$$, verification_status = $$verified$$, source_reliability = 9, is_active = false, university_id = 168, notes = $$PASS 122 RETIREMENT 2026-10-28 (Argentina): invented composite name. CONICET's official Convocatorias 2026 page fetched first-hand today (new source 3135): the real instrument is the national Beca Interna Doctoral (1,000 fellowships in the 2026 call; 60 months from 2027-04-01; applications 2026-07-27 to 2026-08-21 via SIGEVA; 70% prioritised topics/regions, 30% merit), with Finalización (300; 24 months), Postdoctorales (800; call 2027-02-18 to 2027-03-05; 36 months from 2027-08-01) and company-cofunded lines - none of it a UBA-branded track. The call's Bases (which govern foreigner eligibility, stipend amounts and dedication conditions) were NOT fetched in this pass, so no such terms are asserted; CONICET Beca Interna Doctoral is queued as a future-additions candidate under its own name pending a bases-level fetch. UBA-side audit remains record 693 (free undergraduate study for foreigners; no institutional international scholarships; outbound becas). Prior history: invented USD 14,000 + annual August-11 deadline removed 2026-10-26. us 611 deleted (importer 'Fully Funded' claims). Root source 2637 retained; (400, 3135) added for audit.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 400 RETURNING id, is_active;

-- 3) Retire 401 (invented name)
UPDATE scholarships SET title = $$Universidade de São Paulo - 'USP Talented Student Scholarship International Track' is an invented importer name; USP is tuition-free and offers no such scholarship (retired)$$, provider = $$Universidade de Sao Paulo$$, country = $$Brazil$$, coverage_type = $$Unspecified$$, amount_usd_value = 0, award_amount = NULL, award_currency = NULL, award_period = NULL, award_basis = NULL, deadline = $$Retired - no award of this name exists, so there is no application round. USP charges no school fees and offers foreign students no institutional scholarship; the real Brazilian graduate-stipend lane is the CAPES/CNPq/FAPESP agency quotas covered by active record 730.$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[]$$, recurrence = $$none$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Master's", "PhD"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["RETIRED - invented importer name; USP offers foreign students no institutional scholarship (see description)"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$RETIRED in Pass 122 (2026-10-28) as an invented importer name. The Universidade de São Paulo has no "Talented Student Scholarship" and no "International Track" award for foreign students. The university's own position was read on its graduate rectorate's (PRPG) page for foreign students for audit row 777 (2026-10-25): USP is a public and free institution, receives foreign students without charging school fees and therefore does not offer scholarships; its activities are in Portuguese; and the AUCANI international office pages repeat that exchange students are accepted at no cost outside a few paid summer/extension courses. On re-check for this pass (2026-10-28) that PRPG page has moved in the sites.usp.br to prpg.usp.br migration and currently returns the site's not-found page - the institutional fact it stated has not changed: as a tuition-free public university, USP has no tuition for a scholarship to waive and funds no stipends of its own. What Brazilian graduate funding actually looks like is the agency-quota system: CAPES, CNPq and state foundations such as FAPESP award monthly stipends that are distributed through accredited graduate programmes - that lane is covered by active record 730 ("CAPES / CNPq / FAPESP graduate scholarships") and is the realistic route for a foreign master's or PhD student at USP or elsewhere in Brazil. The stipend figures an earlier importer incarnation attached to this row (an invented USD 16,000 and an annual March-31 deadline, removed 2026-10-26) belonged to no published USP instrument; the only USP bolsa money the 2026-10-25 audit found on the university's pages was outbound (grants for USP's own students going abroad, e.g. edital 2242). Use record 730 and USP's official pages, not this record.$$ , requirements = $$Do not apply on the basis of this record - it is retired and names no real award. USP charges foreign students no school fees and offers them no institutional scholarship; for a funded master's/PhD in Brazil, apply to an accredited graduate programme and compete for its CAPES/CNPq/FAPESP stipend quotas (active record 730), noting that study and administration run in Portuguese.$$ , website_url = $$https://www.usp.br/$$, source_url = $$https://www.usp.br/$$, application_url = $$https://www.usp.br/$$, funding_type = $$RETIRED - invented importer name; USP offers no such scholarship$$, tuition_coverage = $$RETIRED - no coverage of its own; the real agency-quota stipend lane is record 730.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = $$Not applicable - retired record.$$ , required_documents = $$[]$$, application_status = $$closed$$, verification_status = $$verified$$, source_reliability = 9, is_active = false, university_id = 185, notes = $$PASS 122 RETIREMENT 2026-10-28 (Brazil): invented importer name. Evidence: USP PRPG foreign-students page read 2026-10-25 for retired audit row 777 ('USP is a public and free institution, receives foreign students without charging school fees and therefore does not offer scholarships'; AUCANI incoming pages corroborate; all activities in Portuguese; the only USP bolsa figures found were outbound, edital 2242). Re-fetch attempts in this pass (2026-10-28): the cited PRPG page now returns the 'Página não encontrada' (404) template on both its English and bare slugs after the sites.usp.br -> prpg.usp.br migration, and the PRPG site's own search returns no replacement foreign-students page - recorded here so the audit trail is honest; the institutional position (tuition-free public university, no international-student scholarships) stands. Real lane: CAPES/CNPq/FAPESP programme quotas = active record 730 (rel 8; future uplift candidate, incl. checking PEC-PG coverage). Prior history: invented USD 16,000 + annual March-31 deadline removed 2026-10-26. us 618 deleted (importer 'Fully Funded' claims). Root source 2680 retained for audit.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 401 RETURNING id, is_active;

